"""Canonical complete database model. No customer data or credentials."""
TABLES=[]
ID="CHAR(26) CHARACTER SET ascii COLLATE ascii_bin"
CODE="VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin"
MONEY="BIGINT"
QTY="DECIMAL(12,3)"
DPT="DECIMAL(6,2)"
MM="DECIMAL(6,2)"

def c(name,typ,nullable=False,default=None,description='',ref=None,generated=None):
    return dict(name=name,type=typ,nullable=nullable,default=default,description=description,ref=ref,generated=generated)
def s(name,size=180,**kw): return c(name,f'VARCHAR({size})',**kw)
def txt(name,**kw): return c(name,'TEXT',**kw)
def dt(name,**kw): return c(name,'DATETIME(6)',**kw)
def date(name,**kw): return c(name,'DATE',**kw)
def flag(name,default='0',**kw): return c(name,'BOOLEAN',default=default,**kw)
def money(name,nullable=False,default=None,**kw): return c(name,MONEY,nullable,default,**kw)
def qty(name,nullable=False,default=None,**kw): return c(name,QTY,nullable,default,**kw)
def js(name,nullable=True,**kw): return c(name,'JSON',nullable,**kw)
def r(name,target,nullable=False,description=''): return c(name,ID,nullable,description=description,ref=target)
def code(name,values=None,nullable=False,default=None,description=''):
    result=c(name,CODE,nullable,default,description)
    result['allowed_values']=values
    return result
def T(name,domain,description,columns,unique=(),indexes=(),checks=(),foreign=(),immutable=False,guard=None):
    columns=[c('id',ID),r('clinic_id','clinics')]+columns+[dt('created_at',default='CURRENT_TIMESTAMP(6)'),dt('updated_at',default='CURRENT_TIMESTAMP(6)')]
    table=dict(name=name,domain=domain,description=description,columns=columns,primary=['id'],unique=[['clinic_id','id']]+[list(x) for x in unique],indexes=[list(x) for x in indexes],checks=list(checks),foreign=list(foreign),immutable=immutable,guard=guard)
    TABLES.append(table)
    return table
def G(name,description,columns,primary,unique=(),checks=()):
    TABLES.append(dict(name=name,domain='Référentiels globaux',description=description,columns=columns,primary=list(primary),unique=[list(x) for x in unique],indexes=[],checks=list(checks),foreign=[],immutable=False,guard=None))
def fk(columns,target,target_columns): return dict(columns=list(columns),target=target,target_columns=list(target_columns))
def version(): return c('version','INT UNSIGNED',default='1',description='Version optimiste, jamais un numéro de pièce')
def actor(name='created_by',nullable=False): return r(name,'users',nullable)
def reason(): return txt('reason',description='Motif obligatoire de l’opération')
def snapshot(): return js('snapshot',nullable=False,description='Données figées de la pièce ou révision')
def h(name='sha256',nullable=False): return c(name,'CHAR(64) CHARACTER SET ascii COLLATE ascii_bin',nullable)
def state(values,default=None,name='status'): return code(name,values,default=default)
def issued_fields(): return [s('number',64,nullable=True),dt('issued_at',nullable=True),actor('issued_by',True)]

