next(x for x in prescription['columns'] if x['name']=='consultation_id')['nullable']=True
prescription['columns'][2:2]=[r('patient_id','patient_records'),c('series_id',ID),code('origin',['INTERNAL','EXTERNAL'],default="'INTERNAL'"),r('external_file_id','stored_files',True),s('external_prescriber',180,nullable=True),date('external_prescribed_on',nullable=True)]
