by_name['stock_reservations']['columns'].insert(2,r('item_id','catalog_items'))
by_name['stock_reservations']['foreign'] += [fk(['clinic_id','invoice_line_id','item_id'],'invoice_lines',['clinic_id','id','catalog_item_id']),fk(['clinic_id','stock_position_id','item_id'],'stock_positions',['clinic_id','id','item_id'])]
for name in ['stock_reservations','device_stock_allocations']:
    by_name[name]['columns'].append(c('lot_key',ID,generated="COALESCE(stock_lot_id,'00000000000000000000000000')"))
by_name['device_stock_allocations']['unique'].append(['clinic_id','id','stock_position_id','lot_key'])
