by_name['communication_consents']['columns'].append(c('subject_key','VARCHAR(28) CHARACTER SET ascii COLLATE ascii_bin',generated="CASE WHEN patient_id IS NOT NULL THEN CONCAT('P:',patient_id) ELSE CONCAT('C:',prospect_contact_id) END"))
