by_name['invoices']['checks']=[expr.replace('legacy_reference IS NOT NULL AND legacy_opening_balance = total_gross','legacy_reference IS NOT NULL AND legacy_opening_balance IS NOT NULL AND legacy_opening_balance = total_gross') for expr in by_name['invoices']['checks']]
by_name['generated_documents']['guard']='ready_document'
by_name['offline_grants']['guard']='signed_grant'
by_name['public_booking_requests']['columns'].insert(2,r('catalog_publication_id','catalog_publications',True))
by_name['follow_up_plans']['checks'] += ['interval_value IS NULL OR interval_value > 0']

# One command may produce N stock effects; each effect has a stable ordinal.
by_name['stock_movements']['columns'].insert(2,c('movement_position','SMALLINT UNSIGNED',default='1'))
by_name['stock_movements']['unique']=[['clinic_id','id'],['clinic_id','idempotency_id','movement_position']]
by_name['stock_movements']['checks'].append('movement_position > 0')

# Workshop order and invoice line necessarily belong to the same patient.
by_name['invoice_lines']['unique'].append(['clinic_id','id','patient_id'])
by_name['workshop_orders']['columns'].insert(2,r('patient_id','patient_records'))
by_name['workshop_orders']['foreign'] += [fk(['clinic_id','invoice_line_id','patient_id'],'invoice_lines',['clinic_id','id','patient_id']),fk(['clinic_id','prescription_id','patient_id'],'optical_prescriptions',['clinic_id','id','patient_id'])]

# Typed source checks for delivery, reservation and physical stock effects.
by_name['delivery_lines']['columns'][2:2]=[r('item_id','catalog_items'),r('stock_position_id','stock_positions',True),c('lot_key',ID,generated="COALESCE(stock_lot_id,'00000000000000000000000000')")]
by_name['delivery_lines']['unique'] += [['clinic_id','id','item_id'],['clinic_id','id','item_id','stock_position_id','lot_key']]
