by_name['goods_receipt_lines']['unique'].append(['clinic_id','id','item_id'])
by_name['stock_movements']['foreign'].append(fk(['clinic_id','goods_receipt_line_id','item_id'],'goods_receipt_lines',['clinic_id','id','item_id']))
by_name['physical_returns']['columns'].insert(2,r('item_id','catalog_items'))
