by_name['physical_returns']['foreign'].append(fk(['clinic_id','delivery_line_id','item_id'],'delivery_lines',['clinic_id','id','item_id']))
by_name['stock_movements']['foreign'].append(fk(['clinic_id','physical_return_id','item_id'],'physical_returns',['clinic_id','id','item_id']))
T('quote_revisions','Catalogue et facturation','Version figée d’un devis remis ou corrigé',[r('quote_id','quotes'),c('revision_no','INT UNSIGNED'),snapshot(),actor('authored_by'),dt('recorded_at'),reason()],unique=[('clinic_id','quote_id','revision_no')],checks=['revision_no > 0'],immutable=True)
by_name={t['name']:t for t in TABLES}
