by_name['appointments']['checks'].append('follow_up_id IS NULL OR patient_id IS NOT NULL')
by_name['visits']['foreign'].append(fk(['clinic_id','exam_invoice_id','id','patient_id'],'invoices',['clinic_id','id','visit_id','patient_id']))
by_name['delivery_lines']['foreign'].append(fk(['clinic_id','workshop_order_id','invoice_line_id'],'workshop_orders',['clinic_id','id','invoice_line_id']))

for table in TABLES:
    names=[col['name'] for col in table['columns']]
    assert len(names)==len(set(names)),table['name']
    for col in table['columns']:
        if col['ref']:
            parent=by_name[col['ref']]
            if col['ref']=='clinics': key=fk([col['name']],'clinics',['id'])
            else: key=fk(['clinic_id',col['name']],col['ref'],['clinic_id','id'])
            if key not in table['foreign']: table['foreign'].append(key)
        if col.get('allowed_values'):
            literals=','.join("'"+v+"'" for v in col['allowed_values'])
            table['checks'].append(f"`{col['name']}` IN ({literals})")
        if col['type']=='BOOLEAN': table['checks'].append(f"`{col['name']}` IN (0,1)")
        if col['type']==MONEY and col['name'] not in ('signed_amount','variance','statement_amount','expected_amount'):
            table['checks'].append(f"`{col['name']}` BETWEEN 0 AND 1000000000000")
    if 'id' in names and next(x for x in table['columns'] if x['name']=='id')['type']==ID:
        table['checks'].append("id <> '00000000000000000000000000'")
